package br.com.sistemacardapio.pedido;

import java.math.BigDecimal;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import br.com.sistemacardapio.catalogo.*;
import br.com.sistemacardapio.empresa.*;
import br.com.sistemacardapio.horario.HorarioService;
import br.com.sistemacardapio.promocao.*;

@Service
public class PedidoService {
    private static final ZoneId ZONE = ZoneId.of("America/Sao_Paulo");
    private final EmpresaRepository empresas; private final ProdutoRepository produtos; private final ProdutoVariacaoRepository variacoes;
    private final PromocaoRepository promocoes; private final JdbcTemplate jdbc; private final HorarioService horarios; private final PedidoEventoService eventos;
    public PedidoService(EmpresaRepository e, ProdutoRepository p, ProdutoVariacaoRepository v, PromocaoRepository pr, JdbcTemplate j, HorarioService h, PedidoEventoService ev) { empresas=e;produtos=p;variacoes=v;promocoes=pr;jdbc=j;horarios=h;eventos=ev; }

    @Transactional
    public Response criar(Request request) {
        Empresa empresa=empresas.findBySlugAndAtivaTrue(request.empresaSlug()).orElseThrow(()->new IllegalStateException("Empresa não encontrada"));
        validarAtendimento(empresa,request); validarAgendamento(empresa,request.agendadoPara());
        UUID cliente=cliente(request); List<ItemCalculado> calculados=new ArrayList<>(); BigDecimal subtotal=BigDecimal.ZERO;
        for(ItemRequest item:request.itens()){ItemCalculado calculado=calcular(empresa,item);calculados.add(calculado);subtotal=subtotal.add(calculado.subtotal());}
        if(calculados.isEmpty())throw new IllegalStateException("Pedido deve possuir itens");if(subtotal.compareTo(empresa.getPedidoMinimo())<0)throw new IllegalStateException("O pedido mínimo é R$ "+empresa.getPedidoMinimo());CupomAplicado cupom=cupom(empresa,cliente,request.cupomCodigo(),subtotal);BigDecimal taxa=taxa(empresa,request,subtotal,cupom);BigDecimal total=subtotal.subtract(cupom.desconto()).add(taxa).max(BigDecimal.ZERO);UUID pedido=UUID.randomUUID(); Long numero=jdbc.queryForObject("select nextval('pedido_numero_seq')",Long.class);
        jdbc.update("insert into pedido(id,empresa_id,cliente_id,numero,cliente_nome,cliente_telefone,modalidade,status,pagamento,troco_para,subtotal,taxa_entrega,total,bairro_entrega_id,endereco_cep,endereco_rua,endereco_numero,endereco_complemento,endereco_bairro,endereco_referencia,agendado_para,cupom_id,cupom_codigo,desconto) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",pedido,empresa.getId(),cliente,numero,request.clienteNome().trim(),normalizarTelefone(request.telefone()),request.modalidade(),"AGUARDANDO_CONTATO",request.pagamento(),request.trocoPara(),subtotal,taxa,total,request.bairroId(),value(request.endereco(),EnderecoRequest::cep),value(request.endereco(),EnderecoRequest::rua),value(request.endereco(),EnderecoRequest::numero),value(request.endereco(),EnderecoRequest::complemento),value(request.endereco(),EnderecoRequest::bairro),value(request.endereco(),EnderecoRequest::referencia),request.agendadoPara(),cupom.id(),cupom.codigo(),cupom.desconto());
        for(ItemCalculado item:calculados){UUID itemId=UUID.randomUUID();jdbc.update("insert into pedido_item(id,pedido_id,produto_id,variacao_id,produto_nome,variacao_nome,quantidade,preco_unitario,subtotal,observacao) values(?,?,?,?,?,?,?,?,?,?)",itemId,pedido,item.produtoId(),item.variacaoId(),item.produtoNome(),item.variacaoNome(),item.quantidade(),item.precoUnitario(),item.subtotal(),item.observacao());for(ComplementoCalculado complemento:item.complementos())jdbc.update("insert into pedido_item_complemento(id,pedido_item_id,complemento_id,complemento_nome,quantidade,preco_unitario) values(?,?,?,?,?,?)",UUID.randomUUID(),itemId,complemento.id(),complemento.nome(),complemento.quantidade(),complemento.preco());}
        jdbc.update("insert into pedido_historico(id,pedido_id,status_anterior,novo_status) values(?,?,?,?)",UUID.randomUUID(),pedido,null,"AGUARDANDO_CONTATO");
        jdbc.update("insert into analytics_evento(id,empresa_id,tipo,sessao) values(gen_random_uuid(),?,'PEDIDO_CRIADO',?)",empresa.getId(),request.sessao());String mensagem=mensagem(numero,request,calculados,subtotal,cupom.desconto(),taxa,total);String whatsapp=normalizarTelefone(empresa.getWhatsapp());if(whatsapp.isBlank())throw new IllegalStateException("WhatsApp da empresa não configurado");eventos.publicar(empresa.getId(),"novo-pedido",Map.of("id",pedido,"numero",numero));
        return new Response(pedido,numero,"AGUARDANDO_CONTATO",subtotal,cupom.desconto(),taxa,total,"https://wa.me/"+whatsapp+"?text="+URLEncoder.encode(mensagem,StandardCharsets.UTF_8),mensagem);
    }

    private void validarAgendamento(Empresa empresa, Instant agendado) {
        boolean aberta=horarios.estaAbertaAgora(empresa.getId());
        if(!aberta&&agendado==null)throw new IllegalStateException("O estabelecimento está fechado. Escolha um horário para agendar.");
        if(agendado==null)return; Instant minimo=Instant.now().plus(20,java.time.temporal.ChronoUnit.MINUTES); Instant maximo=Instant.now().plus(8,java.time.temporal.ChronoUnit.DAYS);
        if(agendado.isBefore(minimo)||agendado.isAfter(maximo))throw new IllegalStateException("Escolha um horário entre 20 minutos e 8 dias a partir de agora");
        if(!horarios.estaAberta(empresa.getId(),LocalDateTime.ofInstant(agendado,ZONE)))throw new IllegalStateException("O horário selecionado está fora do funcionamento da empresa");
    }

    private ItemCalculado calcular(Empresa empresa,ItemRequest request){Produto produto=produtos.findByIdAndEmpresaId(request.produtoId(),empresa.getId()).filter(x->x.isAtivo()&&x.isDisponivel()).orElseThrow(()->new IllegalStateException("Produto indisponível"));if(request.quantidade()<1)throw new IllegalStateException("Quantidade inválida");BigDecimal base;String variacaoNome=null;if(request.variacaoId()!=null){ProdutoVariacao variacao=variacoes.findByIdAndProdutoIdAndEmpresaId(request.variacaoId(),produto.getId(),empresa.getId()).filter(ProdutoVariacao::isAtiva).orElseThrow(()->new IllegalStateException("Variação inválida"));base=variacao.getPreco();variacaoNome=variacao.getNome();}else base=promocoes.findFirstByProdutoIdAndEmpresaIdAndAtivaTrueAndInicioLessThanEqualAndFimGreaterThanOrderByInicioDesc(produto.getId(),empresa.getId(),Instant.now(),Instant.now()).map(Promocao::getPrecoPromocional).orElse(produto.getPreco());Map<UUID,Integer>quantidades=new HashMap<>();for(ComplementoRequest item:request.complementos())quantidades.merge(item.id(),item.quantidade(),Integer::sum);List<ComplementoCalculado>complementos=new ArrayList<>();for(var entry:quantidades.entrySet()){if(entry.getValue()<1)throw new IllegalStateException("Quantidade de complemento inválida");ComplementoCalculado complemento=jdbc.query("select c.id,c.nome,c.preco_adicional from complemento c join produto_grupo_complemento pg on pg.grupo_id=c.grupo_id and pg.empresa_id=c.empresa_id where c.id=? and c.empresa_id=? and pg.produto_id=? and c.ativo=true",rs->rs.next()?new ComplementoCalculado(rs.getObject(1,UUID.class),rs.getString(2),rs.getBigDecimal(3),entry.getValue()):null,entry.getKey(),empresa.getId(),produto.getId());if(complemento==null)throw new IllegalStateException("Complemento inválido");complementos.add(complemento);}validarGrupos(produto.getId(),empresa.getId(),quantidades);BigDecimal soma=complementos.stream().map(x->x.preco().multiply(BigDecimal.valueOf(x.quantidade()))).reduce(BigDecimal.ZERO,BigDecimal::add);int totalComplementos=complementos.stream().mapToInt(ComplementoCalculado::quantidade).sum();BigDecimal adicional="MAIOR_COMPLEMENTO".equals(produto.getRegraPreco())?complementos.stream().map(ComplementoCalculado::preco).max(BigDecimal::compareTo).orElse(BigDecimal.ZERO):"MEDIA_COMPLEMENTOS".equals(produto.getRegraPreco())&&totalComplementos>0?soma.divide(BigDecimal.valueOf(totalComplementos),2,java.math.RoundingMode.HALF_UP):soma;BigDecimal unitario=base.add(adicional);return new ItemCalculado(produto.getId(),request.variacaoId(),produto.getNome(),variacaoNome,request.quantidade(),unitario,unitario.multiply(BigDecimal.valueOf(request.quantidade())),request.observacao(),complementos);}
    private void validarGrupos(UUID produto,UUID empresa,Map<UUID,Integer>selecionados){List<GrupoRegra>regras=jdbc.query("select g.id,g.quantidade_minima,g.quantidade_maxima from grupo_complemento g join produto_grupo_complemento pg on pg.grupo_id=g.id and pg.empresa_id=g.empresa_id where pg.produto_id=? and pg.empresa_id=? and g.ativo=true",(rs,n)->new GrupoRegra(rs.getObject(1,UUID.class),rs.getInt(2),rs.getInt(3)),produto,empresa);for(GrupoRegra grupo:regras){int total=selecionados.entrySet().stream().filter(x->Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from complemento where id=? and grupo_id=?)",Boolean.class,x.getKey(),grupo.id()))).mapToInt(Map.Entry::getValue).sum();if(total<grupo.min()||total>grupo.max())throw new IllegalStateException("Quantidade de complementos fora dos limites do grupo");}}
    private UUID cliente(Request request){String telefone=normalizarTelefone(request.telefone());return jdbc.queryForObject("insert into cliente(id,telefone_normalizado,nome,criado_em,atualizado_em) values(gen_random_uuid(),?,?,now(),now()) on conflict(telefone_normalizado) do update set nome=excluded.nome,atualizado_em=now() returning id",UUID.class,telefone,request.clienteNome().trim());}
    private BigDecimal taxa(Empresa empresa,Request request,BigDecimal subtotal,CupomAplicado cupom){if("RETIRADA".equals(request.modalidade())||cupom.freteGratis()||(empresa.getFreteGratisAcima()!=null&&subtotal.compareTo(empresa.getFreteGratisAcima())>=0))return BigDecimal.ZERO;if("TAXA_FIXA".equals(empresa.getTipoTaxaEntrega()))return empresa.getTaxaEntregaFixa()==null?BigDecimal.ZERO:empresa.getTaxaEntregaFixa();if("TAXA_POR_BAIRRO".equals(empresa.getTipoTaxaEntrega())){if(request.bairroId()==null)throw new IllegalStateException("Selecione o bairro");BigDecimal valor=jdbc.query("select taxa from bairro_entrega where id=? and empresa_id=? and ativo=true",rs->rs.next()?rs.getBigDecimal(1):null,request.bairroId(),empresa.getId());if(valor==null)throw new IllegalStateException("Bairro não atendido");return valor;}return BigDecimal.ZERO;}
    private CupomAplicado cupom(Empresa empresa,UUID cliente,String codigo,BigDecimal subtotal){if(codigo==null||codigo.isBlank())return CupomAplicado.vazio();String normal=codigo.trim().toUpperCase(Locale.ROOT);CupomDados c=jdbc.query("select id,codigo,tipo,valor,pedido_minimo,limite_usos,somente_primeira_compra from cupom where empresa_id=? and codigo=? and ativo=true and inicio<=now() and fim>now()",rs->rs.next()?new CupomDados(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getBigDecimal(4),rs.getBigDecimal(5),(Integer)rs.getObject(6),rs.getBoolean(7)):null,empresa.getId(),normal);if(c==null)throw new IllegalStateException("Cupom inválido ou expirado");if(subtotal.compareTo(c.minimo())<0)throw new IllegalStateException("Este cupom exige pedido mínimo de R$ "+c.minimo());if(c.limite()!=null&&jdbc.queryForObject("select count(*) from pedido where cupom_id=?",Integer.class,c.id())>=c.limite())throw new IllegalStateException("Este cupom atingiu o limite de usos");if(c.primeira()&&Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from pedido where empresa_id=? and cliente_id=?)",Boolean.class,empresa.getId(),cliente)))throw new IllegalStateException("Cupom válido somente na primeira compra");BigDecimal desconto="PERCENTUAL".equals(c.tipo())?subtotal.multiply(c.valor()).divide(BigDecimal.valueOf(100)):"FIXO".equals(c.tipo())?c.valor():BigDecimal.ZERO;return new CupomAplicado(c.id(),c.codigo(),desconto.min(subtotal),"FRETE_GRATIS".equals(c.tipo()));}
    private void validarAtendimento(Empresa empresa,Request request){if(!Set.of("ENTREGA","RETIRADA").contains(request.modalidade()))throw new IllegalStateException("Modalidade inválida");if("ENTREGA".equals(request.modalidade())&&!empresa.isAceitaEntrega())throw new IllegalStateException("Entrega não habilitada");if("RETIRADA".equals(request.modalidade())&&!empresa.isAceitaRetirada())throw new IllegalStateException("Retirada não habilitada");if("ENTREGA".equals(request.modalidade())&&(request.endereco()==null||vazio(request.endereco().rua())||vazio(request.endereco().numero())||vazio(request.endereco().bairro())))throw new IllegalStateException("Endereço incompleto");if(!Set.of("DINHEIRO","PIX","CREDITO","DEBITO").contains(request.pagamento()))throw new IllegalStateException("Pagamento inválido");}
    private String mensagem(Long numero,Request request,List<ItemCalculado>itens,BigDecimal subtotal,BigDecimal desconto,BigDecimal taxa,BigDecimal total){StringBuilder texto=new StringBuilder("NOVO PEDIDO #").append(String.format("%06d",numero)).append("\n\nCliente: ").append(request.clienteNome()).append("\nTelefone: ").append(request.telefone()).append("\nTipo: ").append(request.modalidade());if(request.agendadoPara()!=null)texto.append("\nAgendado para: ").append(DateTimeFormatter.ofPattern("dd/MM 'às' HH:mm").format(LocalDateTime.ofInstant(request.agendadoPara(),ZONE)));if("ENTREGA".equals(request.modalidade())&&request.endereco()!=null){texto.append("\nEndereço: ").append(request.endereco().rua()).append(", ").append(request.endereco().numero()).append(" - ").append(request.endereco().bairro());if(!vazio(request.endereco().complemento()))texto.append(" (" ).append(request.endereco().complemento()).append(")");if(!vazio(request.endereco().referencia()))texto.append(" - Ref.: ").append(request.endereco().referencia());}texto.append("\n\n");for(ItemCalculado item:itens){texto.append(item.quantidade()).append("x ").append(item.produtoNome());if(item.variacaoNome()!=null)texto.append(" - ").append(item.variacaoNome());texto.append('\n');for(ComplementoCalculado complemento:item.complementos())texto.append("  + ").append(complemento.quantidade()).append("x ").append(complemento.nome()).append('\n');if(!vazio(item.observacao()))texto.append("  Obs.: ").append(item.observacao()).append('\n');}texto.append("\nSubtotal: R$ ").append(subtotal);if(desconto.signum()>0)texto.append("\nDesconto: -R$ ").append(desconto);if(taxa.signum()>0)texto.append("\nTaxa: R$ ").append(taxa);texto.append("\nTotal: R$ ").append(total).append("\nPagamento: ").append(request.pagamento());if(request.trocoPara()!=null)texto.append("\nTroco para: R$ ").append(request.trocoPara());return texto.toString();}
    private String normalizarTelefone(String value){return value==null?"":value.replaceAll("\\D","");}private boolean vazio(String value){return value==null||value.isBlank();}private <T>String value(T object,java.util.function.Function<T,String> getter){return object==null?null:getter.apply(object);}
    public record Request(@jakarta.validation.constraints.NotBlank String empresaSlug,@jakarta.validation.constraints.NotBlank String clienteNome,@jakarta.validation.constraints.NotBlank String telefone,@jakarta.validation.constraints.NotBlank String modalidade,UUID bairroId,EnderecoRequest endereco,@jakarta.validation.constraints.NotBlank String pagamento,BigDecimal trocoPara,Instant agendadoPara,String cupomCodigo,String sessao,@jakarta.validation.constraints.NotEmpty List<ItemRequest>itens){}
    public record EnderecoRequest(String cep,String rua,String numero,String complemento,String bairro,String referencia){}public record ItemRequest(@jakarta.validation.constraints.NotNull UUID produtoId,UUID variacaoId,int quantidade,String observacao,List<ComplementoRequest>complementos){public ItemRequest{complementos=complementos==null?List.of():complementos;}}public record ComplementoRequest(UUID id,int quantidade){}public record Response(UUID id,Long numero,String status,BigDecimal subtotal,BigDecimal desconto,BigDecimal taxaEntrega,BigDecimal total,String whatsappUrl,String mensagem){}private record ComplementoCalculado(UUID id,String nome,BigDecimal preco,int quantidade){}private record ItemCalculado(UUID produtoId,UUID variacaoId,String produtoNome,String variacaoNome,int quantidade,BigDecimal precoUnitario,BigDecimal subtotal,String observacao,List<ComplementoCalculado>complementos){}private record GrupoRegra(UUID id,int min,int max){}private record CupomDados(UUID id,String codigo,String tipo,BigDecimal valor,BigDecimal minimo,Integer limite,boolean primeira){}private record CupomAplicado(UUID id,String codigo,BigDecimal desconto,boolean freteGratis){static CupomAplicado vazio(){return new CupomAplicado(null,null,BigDecimal.ZERO,false);}}
}
